import re

def _get_node(doc, item):
    return item if isinstance(item, dict) else node_by_id(doc, item)

def _find_node(doc, scope_children, kind, title_contains):
    for item in scope_children:
        node = _get_node(doc, item)
        if node and node.get("kind") == kind and title_contains in node.get("title", ""):
            return node
    return None

def entities(doc, scope):
    scope_children = scope_nodes(doc, scope)
    obj_node = _find_node(doc, scope_children, "list", "Objects")
    if not obj_node:
        return []
    res = []
    for li, line in enumerate(obj_node.get("lines", [])):
        m = re.match(r'Object (\d+):\s*(.+?)\s*\(', line)
        if m:
            res.append({"id": m.group(1), "description": m.group(2).strip()})
    return res

def recorded_end(doc, scope):
    scope_children = scope_nodes(doc, scope)
    max_frame = None
    motion_node = _find_node(doc, scope_children, "table", "Motion log")
    if motion_node:
        for ri, row in table_rows(motion_node):
            try:
                f = float(row["frame"])
                if max_frame is None or f > max_frame:
                    max_frame = f
            except (ValueError, KeyError):
                pass
    events_node = _find_node(doc, scope_children, "list", "Events")
    if events_node:
        for li, line in enumerate(events_node.get("lines", [])):
            m = re.match(r'Frame (\d+):', line)
            if m:
                f = float(m.group(1))
                if max_frame is None or f > max_frame:
                    max_frame = f
    return max_frame

def inputs(doc, scope):
    scope_children = scope_nodes(doc, scope)
    obj_node = _find_node(doc, scope_children, "list", "Objects")
    evt_node = _find_node(doc, scope_children, "list", "Events")
    mot_node = _find_node(doc, scope_children, "table", "Motion log")

    obj_props = {}
    obj_srcs = {}
    if obj_node:
        for li, line in enumerate(obj_node.get("lines", [])):
            m = re.match(r'Object (\d+):\s*.+?\((.+)\)', line)
            if m:
                oid = m.group(1)
                props = {}
                for part in m.group(2).split(', '):
                    if '=' in part:
                        k, v = part.split('=', 1)
                        props[k.strip()] = v.strip()
                obj_props[oid] = props
                obj_srcs[oid] = [obj_node["node_id"], li]

    result = []
    counter = 0
    if evt_node:
        for li, line in enumerate(evt_node.get("lines", [])):
            m_in_view = re.match(r'Frame (\d+):\s*Object (\d+)\s*\([^)]*\)\s+is in view when the video begins', line)
            m_enters = re.match(r'Frame (\d+):\s*Object (\d+)\s*\([^)]*\)\s+enters the scene', line)
            m = m_in_view or m_enters
            if m:
                frame = float(m.group(1))
                oid = m.group(2)
                kind = "present_at_start" if m_in_view else "enters"
                fields = dict(obj_props.get(oid, {}))
                src = [[evt_node["node_id"], li]]
                if oid in obj_srcs:
                    src.append(obj_srcs[oid])

                if mot_node:
                    for ri, row in table_rows(mot_node):
                        try:
                            r_oid = row["object"].split()[0]
                            r_frame = float(row["frame"])
                            if r_oid == oid and abs(r_frame - frame) < 0.5:
                                fields["x"] = float(row["x"])
                                fields["y"] = float(row["y"])
                                fields["vx"] = float(row["vx"])
                                fields["vy"] = float(row["vy"])
                                fields["speed"] = float(row["speed"])
                                src.append([mot_node["node_id"], ri, ["frame", "object", "x", "y", "vx", "vy", "speed"]])
                                break
                        except (ValueError, KeyError, IndexError):
                            pass

                result.append({
                    "id": f"input_{counter}",
                    "time": frame,
                    "kind": kind,
                    "entities": [oid],
                    "fields": fields,
                    "src": src
                })
                counter += 1
    return result

def outcomes(doc, scope):
    scope_children = scope_nodes(doc, scope)
    evt_node = _find_node(doc, scope_children, "list", "Events")
    if not evt_node:
        return []
    result = []
    for li, line in enumerate(evt_node.get("lines", [])):
        m_coll = re.match(r'Frame (\d+):\s*Object (\d+)\s*\([^)]*\)\s+collides with Object (\d+)\s*\([^)]*\)', line)
        m_exit = re.match(r'Frame (\d+):\s*Object (\d+)\s*\([^)]*\)\s+exits the scene', line)

        if m_coll:
            result.append({
                "time": float(m_coll.group(1)),
                "kind": "collision",
                "entities": [m_coll.group(2), m_coll.group(3)],
                "value": None,
                "src": [[evt_node["node_id"], li]]
            })
        elif m_exit:
            result.append({
                "time": float(m_exit.group(1)),
                "kind": "exits",
                "entities": [m_exit.group(2)],
                "value": None,
                "src": [[evt_node["node_id"], li]]
            })
    return result

def params(doc, scope):
    return {"stationary_speed_threshold": 0.1}


