import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_speed_threshold", 0.1)

    # Physics parameters estimated from data
    POS_SCALE = 0.028   # position update scale per frame
    VEL_DECAY = 0.993   # velocity decay factor per frame (friction)
    COLLISION_DIST = 0.42  # distance threshold for collision
    COR = 0.5           # coefficient of restitution
    MASS_RUBBER = 1.0
    MASS_METAL = 2.0
    EXIT_BOUND = 3.0    # exit boundary

    # Get entity materials from document
    scope_node = node_by_title(doc, scope)
    scope_children = scope_nodes(doc, scope_node)
    obj_materials = {}

    obj_node = _find_node(doc, scope_children, "list", "Objects")
    if obj_node:
        for line in obj_node.get("lines", []):
            m = re.match(r'Object (\d+):\s*(.+)', line)
            if m:
                oid = m.group(1)
                desc = m.group(2)
                obj_materials[oid] = 'metal' if 'metal' in desc else 'rubber'

    def get_mass(oid):
        return MASS_METAL if obj_materials.get(oid, 'rubber') == 'metal' else MASS_RUBBER

    # Get end time
    end = recorded_end(doc, scope)
    if start is None:
        start = 0
    if horizon is None:
        horizon = end

    if horizon is None:
        return []

    # Parse all inputs and track object entry states
    all_objects = {}
    for inp in inputs:
        for eid in inp["entities"]:
            t = inp["time"]
            fields = inp["fields"]
            all_objects[eid] = {
                "x": float(fields.get("x", 0.0)),
                "y": float(fields.get("y", 0.0)),
                "vx": float(fields.get("vx", 0.0)),
                "vy": float(fields.get("vy", 0.0)),
                "entry_time": float(t),
            }

    # Find earliest entry time
    if not all_objects:
        return []
    earliest = min(info["entry_time"] for info in all_objects.values())
    start_t = max(0, int(earliest))
    end_t = int(horizon)

    # Simulate from earliest entry to horizon
    active = {}  # eid -> {x, y, vx, vy}
    collision_pairs = set()  # Track which pairs have already collided
    all_outcomes = []

    for t in range(start_t, end_t + 1):
        # Add objects that enter at this frame
        for eid, info in all_objects.items():
            if int(info["entry_time"]) == t and eid not in active:
                active[eid] = {
                    "x": info["x"],
                    "y": info["y"],
                    "vx": info["vx"],
                    "vy": info["vy"],
                }

        # Update positions (move objects forward)
        for eid, obj in active.items():
            obj["x"] += obj["vx"] * POS_SCALE
            obj["y"] += obj["vy"] * POS_SCALE

        # Check for collisions
        active_eids = list(active.keys())
        for i in range(len(active_eids)):
            for j in range(i + 1, len(active_eids)):
                eid1 = active_eids[i]
                eid2 = active_eids[j]
                pair = tuple(sorted([eid1, eid2]))

                if pair in collision_pairs:
                    continue

                obj1 = active[eid1]
                obj2 = active[eid2]

                dx = obj2["x"] - obj1["x"]
                dy = obj2["y"] - obj1["y"]
                dist = math.sqrt(dx * dx + dy * dy)

                if dist < COLLISION_DIST:
                    collision_pairs.add(pair)

                    # Collision normal (from obj1 to obj2)
                    if dist > 0.001:
                        nx, ny = dx / dist, dy / dist
                    else:
                        nx, ny = 1.0, 0.0

                    # Relative velocity
                    vrel_x = obj1["vx"] - obj2["vx"]
                    vrel_y = obj1["vy"] - obj2["vy"]
                    vrel_n = vrel_x * nx + vrel_y * ny

                    # Only respond if objects are approaching
                    if vrel_n > 0:
                        m1 = get_mass(eid1)
                        m2 = get_mass(eid2)
                        inv_mass_sum = 1.0 / m1 + 1.0 / m2

                        impulse = -(1.0 + COR) * vrel_n / inv_mass_sum

                        obj1["vx"] += impulse * nx / m1
                        obj1["vy"] += impulse * ny / m1
                        obj2["vx"] -= impulse * nx / m2
                        obj2["vy"] -= impulse * ny / m2

                    all_outcomes.append({
                        "time": float(t),
                        "kind": "collision",
                        "entities": [eid1, eid2],
                        "value": None,
                        "src": [],
                    })

        # Decay velocities and check stationary
        for eid, obj in active.items():
            obj["vx"] *= VEL_DECAY
            obj["vy"] *= VEL_DECAY

            speed = math.sqrt(obj["vx"] ** 2 + obj["vy"] ** 2)
            if speed < stationary_threshold:
                obj["vx"] = 0.0
                obj["vy"] = 0.0

        # Check for exits
        for eid in list(active.keys()):
            obj = active[eid]
            if abs(obj["x"]) > EXIT_BOUND or abs(obj["y"]) > EXIT_BOUND:
                all_outcomes.append({
                    "time": float(t),
                    "kind": "exits",
                    "entities": [eid],
                    "value": None,
                    "src": [],
                })
                del active[eid]

    # Return only outcomes at or after start
    return [o for o in all_outcomes if o["time"] >= start]

